class BaseClass(object):

    def __init__(self):
        self._spam = 5

    @property
    def spam(self):
        """BaseClass.getter"""
        return self._spam

    @spam.setter
    def spam(self, value):
        self._spam = value

    @spam.deleter
    def spam(self):
        del self._spam

def _t():
    base = BaseClass()
    assert base.spam == 5, ('assertEqual', base.spam, 5)
    assert base._spam == 5, ('assertEqual', base._spam, 5)
    base.spam = 10
    assert base.spam == 10, ('assertEqual', base.spam, 10)
    assert base._spam == 10, ('assertEqual', base._spam, 10)
    delattr(base, 'spam')
    assert not hasattr(base, 'spam'), ('assertNotHasAttr', base, 'spam')
    assert not hasattr(base, '_spam'), ('assertNotHasAttr', base, '_spam')
    base.spam = 20
    assert base.spam == 20, ('assertEqual', base.spam, 20)
    assert base._spam == 20, ('assertEqual', base._spam, 20)
try:
    _t()
except BaseException as _e:
