class BaseClass(object):

    def __init__(self):
        self._spam = 5

    @property
    def spam(self):
        """BaseClass.getter"""
        return self._spam

    @spam.setter
    def spam(self, value):
        self._spam = value

    @spam.deleter
    def spam(self):
        del self._spam

class SubClass(BaseClass):

    @BaseClass.spam.getter
    def spam(self):
        """SubClass.getter"""
        raise PropertyGet(self._spam)

    @spam.setter
    def spam(self, value):
        raise PropertySet(self._spam)

    @spam.deleter
    def spam(self):
        raise PropertyDel(self._spam)

def _t():
    sub = SubClass()
    try:
        getattr(*(sub, 'spam'))
    except PropertyGet:
        pass
    try:
        setattr(*(sub, 'spam', None))
    except PropertySet:
        pass
    try:
        delattr(*(sub, 'spam'))
    except PropertyDel:
        pass
try:
    _t()
except BaseException as _e:
